export const EDITORIAL_INTRO_BODIES_11_TO_15_V3: Readonly<
  Partial<Record<11 | 12 | 13 | 14 | 15, readonly [LocalizedSource, LocalizedSource, LocalizedSource]>>
> = Object.freeze({
  11: [
    L({
      ru: 'You are ready. сообщает: «Ты готов». Если нужно спросить, are выходит вперёд: Are you ready? Слова не меняются, но новый порядок сразу предупреждает собеседника о вопросе. В обычной нейтральной речи вопрос начинается именно с are, а не только отличается интонацией. Так собеседник понимает ваше намерение ещё до слова ready.',
      uk: 'You are ready. повідомляє: «Ти готовий». Щоб запитати, are виходить уперед: Are you ready? Слова не змінюються, але новий порядок одразу попереджає співрозмовника про запитання. У звичайній нейтральній мові запитання починається саме з are, а не відрізняється лише інтонацією. Намір чути ще до слова ready.',
      es: 'You are ready. afirma que la otra persona está lista. Para preguntarlo, are pasa al principio: Are you ready? Las palabras siguen siendo las mismas, pero el nuevo orden avisa desde el comienzo que esperas una respuesta. En una pregunta neutral, are abre la frase; la entonación no hace todo el trabajo.',
      'pt-BR': 'You are ready. afirma que a outra pessoa está pronta. Para perguntar, are vai para a frente: Are you ready? As palavras continuam iguais, mas a nova ordem avisa desde o início que você espera uma resposta. Numa pergunta neutra, are abre a frase; a entonação não faz todo o trabalho. Assim a intenção fica clara antes mesmo de ready.',
      vi: 'You are ready. cho biết người nghe đã sẵn sàng. Khi hỏi, đưa are lên đầu: Are you ready? Các từ vẫn giữ nguyên, nhưng trật tự mới báo ngay rằng bạn đang chờ câu trả lời. Trong câu hỏi trung tính, are phải mở đầu; chỉ đổi giọng thôi chưa đủ. Người nghe hiểu ý định trước khi nghe đến ready. Đây là dấu hiệu dễ nghe nhất.',
      id: 'You are ready. menyatakan bahwa lawan bicara siap. Untuk bertanya, pindahkan are ke depan: Are you ready? Kata-katanya tetap sama, tetapi urutan baru langsung memberi tanda bahwa kamu menunggu jawaban. Dalam pertanyaan netral, are membuka kalimat; intonasi saja tidak cukup. Maksudnya sudah jelas sebelum kata ready terdengar.',
      tr: 'You are ready. karşındaki kişinin hazır olduğunu söyler. Sormak için are başa geçer: Are you ready? Sözcükler aynı kalır, fakat yeni sıra daha ilk anda cevap beklendiğini gösterir. Nötr bir soruda cümleyi are açar; yalnız tonlama yeterli değildir. Niyet ready duyulmadan anlaşılır. En açık işaret budur.',
      pl: 'You are ready. mówi, że rozmówca jest gotowy. Gdy pytasz, are przechodzi na początek: Are you ready? Słowa zostają te same, lecz nowy szyk od razu pokazuje, że oczekujesz odpowiedzi. W neutralnym pytaniu zdanie otwiera are; sama intonacja nie wystarcza. Zamiar słychać jeszcze przed ready. To najprostszy sygnał pytania.',
    }),
    L({
      ru: 'Начало Are you остаётся одним и тем же. Are you calm? спрашивает о состоянии, а Are you here? — о месте. После you ставится именно та информация, которую хочется проверить. Последнее слово меняет тему вопроса, но не пару are + you и не её порядок. Произносите Are you как цельное начало, а затем добавляйте нужный конец.',
      uk: 'Початок Are you залишається незмінним. Are you calm? питає про стан, а Are you here? — про місце. Після you ставиться саме та інформація, яку треба перевірити. Останнє слово змінює тему запитання, але не пару are + you і не її порядок. Вимовляйте Are you як цілісний початок, а потім додавайте потрібний кінець.',
      es: 'El comienzo Are you se mantiene. Are you calm? pregunta por un estado; Are you here? pregunta por un lugar. Después de you aparece exactamente la información que quieres comprobar. La última palabra cambia el tema, pero no cambia la pareja are + you ni su orden. Pronuncia Are you como un inicio unido y añade después el final que necesitas.',
      'pt-BR': 'O começo Are you não muda. Are you calm? pergunta sobre um estado; Are you here? pergunta sobre um lugar. Depois de you vem exatamente a informação que você quer confirmar. A última palavra muda o assunto, mas não altera a dupla are + you nem sua ordem. Diga Are you como um início unido e acrescente o final necessário.',
      vi: 'Phần mở đầu Are you luôn giữ nguyên. Are you calm? hỏi trạng thái; Are you here? hỏi nơi chốn. Sau you là đúng thông tin bạn muốn kiểm tra. Từ cuối làm đổi chủ đề của câu hỏi, nhưng không làm đổi cặp are + you hay trật tự của cặp đó. Hãy nói liền Are you rồi mới thêm phần cuối cần hỏi. Như vậy câu luôn rõ ràng.',
      id: 'Awal Are you tetap sama. Are you calm? menanyakan keadaan; Are you here? menanyakan tempat. Setelah you, sebutkan informasi yang benar-benar ingin diperiksa. Kata terakhir mengubah topik pertanyaan, bukan pasangan are + you atau urutannya. Ucapkan Are you sebagai satu awal, lalu tambahkan bagian akhir yang diperlukan.',
      tr: 'Are you başlangıcı değişmez. Are you calm? durumu, Are you here? yeri sorar. You sonrasında gerçekten öğrenmek istediğin bilgi gelir. Son sözcük sorunun konusunu değiştirir, fakat are + you çiftini ve sırasını değiştirmez. Are you başlangıcını birlikte söyleyip gereken sonu ekleyin. Böylece soru açık kalır.',
      pl: 'Początek Are you pozostaje taki sam. Are you calm? pyta o stan, a Are you here? o miejsce. Po you pojawia się dokładnie ta informacja, którą chcesz sprawdzić. Ostatnie słowo zmienia temat pytania, lecz nie zmienia pary are + you ani jej szyku. Powiedz Are you jako jeden początek, a potem dodaj potrzebne zakończenie.',
    }),
    L({
      ru: 'Are само умеет начинать вопрос с to be. Поэтому Do you are ready? соединяет два разных способа и звучит неправильно. Нужная форма короче: Are you ready? То же правило даёт Are you calm? — без do. Если в начале уже стоит are, второй вопросительный помощник не добавляется. Смотрите на первое слово: оно уже выполняет всю работу.',
      uk: 'Are саме вміє починати запитання з to be. Тому Do you are ready? змішує два різні способи й звучить неправильно. Потрібна форма коротша: Are you ready? Те саме правило дає Are you calm? — без do. Якщо на початку вже стоїть are, другий питальний помічник не додається. Дивіться на перше слово: воно вже робить усю роботу.',
      es: 'Are puede abrir por sí sola una pregunta con to be. Por eso Do you are ready? mezcla dos maneras distintas y suena mal. La forma necesaria es más corta: Are you ready? La misma regla produce Are you calm?, sin do. Si are ya está al principio, no se añade otro auxiliar. Mira la primera palabra: ya cumple toda la función interrogativa.',
      'pt-BR': 'Are consegue abrir sozinho uma pergunta com to be. Por isso Do you are ready? mistura duas formas diferentes e soa errado. A forma necessária é mais curta: Are you ready? A mesma regra forma Are you calm?, sem do. Se are já está no começo, não se acrescenta outro auxiliar. Observe a primeira palavra: ela já faz todo o trabalho da pergunta.',
      vi: 'Are tự đứng đầu để tạo câu hỏi với to be. Vì vậy Do you are ready? trộn hai cách hỏi khác nhau và nghe sai. Dạng cần dùng ngắn hơn: Are you ready? Quy tắc đó cũng tạo Are you calm? mà không cần do. Khi are đã đứng đầu, không thêm trợ từ hỏi khác. Chỉ cần nhìn từ đầu tiên để nhận ra cấu trúc và biết rằng câu đang chờ một câu trả lời.',
      id: 'Are dapat membuka sendiri pertanyaan dengan to be. Karena itu Do you are ready? mencampur dua cara berbeda dan terdengar salah. Bentuk yang diperlukan lebih pendek: Are you ready? Aturan yang sama membentuk Are you calm? tanpa do. Jika are sudah di depan, jangan tambahkan pembantu lain. Lihat kata pertama: tugas pertanyaan sudah selesai di sana.',
      tr: 'Are, to be sorusunu tek başına başlatabilir. Bu yüzden Do you are ready? iki ayrı soru yolunu karıştırır ve yanlış duyulur. Gereken biçim daha kısadır: Are you ready? Aynı kural Are you calm? sorusunu do olmadan kurar. Başta are varsa başka yardımcı eklenmez. İlk sözcük soru görevini zaten tamamlar.',
      pl: 'Are potrafi samo otworzyć pytanie z to be. Dlatego Do you are ready? miesza dwa różne sposoby i brzmi źle. Potrzebna forma jest krótsza: Are you ready? Ta sama zasada tworzy Are you calm? bez do. Jeśli na początku stoi już are, nie dodaje się drugiego czasownika pomocniczego. Spójrz na pierwsze słowo: ono wykonuje już całą pracę pytania.',
    }),
  ],
  12: [
    L({
      ru: 'I am ready. сообщает о себе: «Я готов». Чтобы не утверждать, а проверить это, am выходит перед I: Am I ready? По-русски те же слова становятся вопросом благодаря интонации, поэтому перестановку легко забыть. В английском нейтральный вопрос виден уже по началу Am I, ещё до слова ready. Если первым остаётся I, собеседник слышит начало утверждения, а не вопроса.',
      uk: 'I am ready. повідомляє про себе: «Я готовий». Щоб не стверджувати, а перевірити це, am виходить перед I: Am I ready? Українською ті самі слова стають запитанням завдяки інтонації, тому перестановку легко пропустити. В англійській нейтральне запитання видно вже з початку Am I, ще до слова ready. Якщо першим лишається I, співрозмовник чує початок твердження, а не запитання.',
      es: 'I am ready. afirma «estoy listo». Para comprobarlo en vez de afirmarlo, am pasa delante de I: Am I ready? En español la forma estoy ya contiene a la persona y los signos o la entonación marcan la pregunta, de modo que yo puede desaparecer. El inglés separa esas piezas y hace visible la pregunta con el orden Am I desde el primer momento. Si empiezas con I am, el oyente espera una afirmación.',
      'pt-BR': 'I am ready. afirma «estou pronto». Para confirmar isso em vez de afirmar, am passa para antes de I: Am I ready? Em português, estou já identifica a pessoa e a entonação pode transformar a mesma ordem em pergunta. O inglês mostra I e am separadamente e avisa que é pergunta pela ordem Am I logo no começo. Se a frase começa com I am, ela soa como uma afirmação.',
      vi: 'I am ready. là lời khẳng định “tôi đã sẵn sàng”. Khi muốn kiểm tra điều đó, tiếng Anh đưa am lên trước I: Am I ready? Tiếng Việt thường giữ thứ tự “tôi + trạng thái” rồi thêm chưa hoặc dùng ngữ điệu ở cuối. Tiếng Anh báo hiệu câu hỏi ngay từ đầu bằng Am I, trước khi người nghe biết trạng thái nào đang được hỏi. Nếu mở đầu bằng I am, câu sẽ được nghe như một lời khẳng định.',
      id: 'I am ready. menyatakan “saya siap”. Untuk memeriksanya, bukan menyatakannya, bahasa Inggris memindahkan am ke depan I: Am I ready? Bahasa Indonesia dapat memakai apakah atau intonasi tanpa menukar urutan saya dan siap. Bahasa Inggris menampilkan penanda pertanyaan sejak awal melalui urutan Am I. Jika kalimat dimulai dengan I am, pendengar mengharapkan sebuah pernyataan.',
      tr: 'I am ready. “Hazırım” diye bir bildirim yapar. Bunu bildirmek yerine sorgulamak için am, I önüne geçer: Am I ready? Türkçede soru anlamı hazır mıyım sözündeki mı ekiyle sonda belirir ve kişi bilgisi de ekte taşınır. İngilizce ise soruyu daha ilk iki sözcükte Am I sırasıyla gösterir. Başlangıç I am olursa dinleyen bir bildirim bekler.',
      pl: 'I am ready. oznajmia „jestem gotowy”. Gdy chcesz to sprawdzić, a nie stwierdzić, am przechodzi przed I: Am I ready? Po polsku pytanie może zaczynać się od czy, a forma jestem już wskazuje osobę. Angielski pokazuje osobno I i am oraz sygnalizuje pytanie szykiem Am I od pierwszych słów. Początek I am zapowiada stwierdzenie, nie neutralne pytanie.',
    }),
    L({
      ru: 'Начало Am I остаётся устойчивым, а после него называется то, что вы хотите проверить. Am I calm? спрашивает о состоянии, Am I here? — о месте, Am I at home? — о том, дома ли вы. Последняя часть меняет содержание вопроса, но не форму am и не её место перед I. Удобно произносить Am I как один вопросительный старт, а затем добавлять точный признак или место. Так порядок не приходится собирать заново для каждого вопроса.',
      uk: 'Початок Am I залишається сталим, а після нього називається те, що ви хочете перевірити. Am I calm? питає про стан, Am I here? — про місце, Am I at home? — чи ви вдома. Остання частина змінює зміст запитання, але не форму am і не її місце перед I. Зручно вимовляти Am I як один питальний початок, а потім додавати точну ознаку або місце. Тоді порядок не доводиться складати заново для кожного запитання.',
      es: 'El comienzo Am I se mantiene y después aparece exactamente lo que quieres comprobar. Am I calm? pregunta por tu estado; Am I here? por tu ubicación; Am I at home? por estar en casa. La parte final cambia el contenido, pero no cambia am ni su posición delante de I. Conviene pronunciar Am I como un inicio interrogativo unido y añadir luego la cualidad o el lugar. Así no reconstruyes el orden cada vez que formulas una pregunta.',
      'pt-BR': 'O começo Am I permanece e depois vem exatamente o que você quer confirmar. Am I calm? pergunta sobre seu estado; Am I here? sobre sua localização; Am I at home? sobre estar em casa. A parte final muda o conteúdo, mas não muda am nem sua posição antes de I. Vale dizer Am I como um início interrogativo unido e acrescentar depois a característica ou o lugar. Assim a ordem não precisa ser refeita em cada pergunta.',
      vi: 'Phần mở đầu Am I giữ nguyên, còn phía sau là điều bạn muốn kiểm tra. Am I calm? hỏi về trạng thái; Am I here? hỏi về vị trí; Am I at home? hỏi bạn có ở nhà hay không. Phần cuối làm thay đổi nội dung, nhưng am vẫn đứng trước I. Hãy coi Am I là một cụm mở đầu câu hỏi rồi thêm đặc điểm hoặc nơi chốn cần xác nhận. Nhờ vậy bạn không phải sắp xếp lại toàn bộ câu mỗi lần hỏi.',
      id: 'Awal Am I tetap sama, lalu bagian setelahnya menyebut hal yang ingin kamu pastikan. Am I calm? menanyakan keadaan; Am I here? menanyakan lokasi; Am I at home? menanyakan apakah kamu berada di rumah. Bagian akhir mengubah isi pertanyaan, tetapi bentuk am dan posisinya sebelum I tidak berubah. Ucapkan Am I sebagai satu awal pertanyaan, kemudian tambahkan sifat atau tempat yang tepat. Dengan begitu urutannya tidak perlu dibangun ulang setiap kali.',
      tr: 'Am I başlangıcı değişmez; ardından doğrulamak istediğiniz durum ya da yer gelir. Am I calm? sakin olup olmadığınızı, Am I here? burada olup olmadığınızı, Am I at home? ise evde olup olmadığınızı sorar. Son bölüm sorunun içeriğini değiştirir, fakat am biçimini ve I önündeki yerini değiştirmez. Am I bölümünü tek bir soru başlangıcı gibi söyleyip gereken özellik ya da yeri ekleyin. Böylece her soruda sırayı baştan kurmazsınız.',
      pl: 'Początek Am I pozostaje stały, a po nim pojawia się to, co chcesz sprawdzić. Am I calm? pyta o stan, Am I here? o miejsce, a Am I at home? o to, czy jesteś w domu. Końcowa część zmienia treść pytania, lecz nie formę am ani jej miejsca przed I. Warto wymawiać Am I jako jeden początek pytania, a potem dodawać właściwą cechę lub miejsce. Dzięki temu nie układasz szyku od nowa przy każdym pytaniu.',
    }),
    L({
      ru: 'Am I ready? — нейтральный вопрос: вы просто проверяете готовность. Am I not ready? уже содержит предположение «я не готов?» и просит подтвердить именно его. В этой полной форме not ставится после I: сначала вопросительное Am I, затем отрицание и признак. Порядок Am not I ready? звучит неестественно и ломает знакомую пару Am I. Не добавляйте not автоматически: оно нужно только тогда, когда отрицательный смысл действительно важен.',
      uk: 'Am I ready? — нейтральне запитання: ви просто перевіряєте готовність. Am I not ready? уже містить припущення «я не готовий?» і просить підтвердити саме його. У цій повній формі not стоїть після I: спочатку питальне Am I, потім заперечення й ознака. Порядок Am not I ready? звучить неприродно та руйнує знайому пару Am I. Не додавайте not автоматично: воно потрібне лише тоді, коли заперечний зміст справді важливий.',
      es: 'Am I ready? es una pregunta neutral: solo compruebas si estás listo. Am I not ready? introduce la idea negativa «¿no estoy listo?» y pide confirmar precisamente esa duda. En esta forma completa, not va después de I: primero aparece el inicio interrogativo Am I y luego la negación. Am not I ready? rompe ese inicio y no es el orden natural. No añadas not por costumbre; úsalo únicamente cuando quieras preguntar por la posibilidad negativa.',
      'pt-BR': 'Am I ready? é uma pergunta neutra: você apenas confirma se está pronto. Am I not ready? introduz a ideia negativa «não estou pronto?» e pede confirmação dessa dúvida. Nesta forma completa, not vem depois de I: primeiro aparece o início interrogativo Am I e depois a negação. Am not I ready? quebra esse início e não é a ordem natural. Não acrescente not por hábito; use-o somente quando a possibilidade negativa fizer parte da pergunta.',
      vi: 'Am I ready? là câu hỏi trung tính: bạn chỉ muốn biết mình đã sẵn sàng hay chưa. Am I not ready? đưa thêm giả định phủ định “tôi chưa sẵn sàng phải không?” và yêu cầu xác nhận giả định đó. Trong dạng đầy đủ này, not đứng sau I: trước hết là phần hỏi Am I, sau đó mới đến phủ định. Am not I ready? phá vỡ cụm mở đầu tự nhiên Am I. Đừng tự động thêm not; chỉ dùng nó khi chính ý phủ định là điều cần hỏi.',
      id: 'Am I ready? adalah pertanyaan netral: kamu hanya memeriksa apakah sudah siap. Am I not ready? membawa dugaan negatif “apakah saya belum siap?” dan meminta kepastian tentang dugaan itu. Dalam bentuk lengkap ini, not berada setelah I: awal pertanyaannya Am I, kemudian baru penyangkalan. Am not I ready? memecah awal alami Am I dan urutannya keliru. Jangan menambahkan not secara otomatis; gunakan hanya ketika makna negatif memang ingin ditanyakan.',
      tr: 'Am I ready? nötr bir sorudur; yalnızca hazır olup olmadığınızı kontrol eder. Am I not ready? ise “hazır değil miyim?” olumsuz varsayımını ekler ve onu doğrulatır. Bu açık biçimde not, I sonrasında gelir: önce soru başlangıcı Am I, ardından olumsuzluk ve özellik yer alır. Am not I ready? doğal Am I çiftini böler ve yanlış sıradır. Not sözcüğünü alışkanlıkla eklemeyin; yalnız olumsuz ihtimali gerçekten sormak istediğinizde kullanın.',
      pl: 'Am I ready? jest pytaniem neutralnym: po prostu sprawdzasz gotowość. Am I not ready? dodaje negatywne przypuszczenie „czy nie jestem gotowy?” i prosi o potwierdzenie właśnie tej wątpliwości. W tej pełnej formie not stoi po I: najpierw pojawia się pytające Am I, a potem przeczenie i cecha. Am not I ready? rozdziela naturalną parę Am I i ma błędny szyk. Nie dodawaj not automatycznie; użyj go tylko wtedy, gdy pytasz o możliwość negatywną.',
    }),
  ],
  13: [
    L({
      ru: 'You’re ready. означает ровно то же, что You are ready.: «Ты готов». Апостроф показывает место пропущенной буквы a, поэтому are не исчезает из смысла и грамматики. Форма You ready. короче только внешне: без are слова больше не соединены в английское утверждение. В разговоре сокращение You’re звучит естественно, а полная форма You are помогает проверить, что именно спрятано внутри. Значит, короткая форма для You are ready. — You’re ready.',
      uk: 'You’re ready. означає те саме, що You are ready.: «Ти готовий». Апостроф показує місце пропущеної літери a, тому are не зникає зі змісту чи граматики. Форма You ready. лише виглядає коротшою: без are слова вже не утворюють англійського твердження. У розмові скорочення You’re звучить природно, а повна форма You are допомагає побачити, що саме сховано всередині. Отже, коротка форма для You are ready. — You’re ready.',
      es: 'You’re ready. significa exactamente lo mismo que You are ready.: «estás listo». El apóstrofo ocupa el lugar de la letra a que se ha omitido, de modo que are sigue presente en el sentido y en la gramática. You ready. solo parece más breve: sin are las palabras ya no forman una afirmación inglesa completa. En una conversación, You’re suena natural; la forma plena You are permite comprobar qué contiene la contracción. Por eso la forma corta de You are ready. es You’re ready.',
      'pt-BR': 'You’re ready. tem exatamente o mesmo sentido de You are ready.: «você está pronto». O apóstrofo ocupa o lugar da letra a que foi omitida, portanto are continua presente no sentido e na gramática. You ready. só parece mais curto: sem are, as palavras não formam uma afirmação inglesa completa. Na conversa, You’re soa natural; a forma completa You are ajuda a conferir o que existe dentro da contração. Assim, a forma curta de You are ready. é You’re ready.',
      vi: 'You’re ready. có nghĩa hoàn toàn giống You are ready.: “bạn đã sẵn sàng”. Dấu nháy đơn đánh dấu vị trí chữ a bị lược đi, vì vậy nghĩa và chức năng của are vẫn còn nguyên. You ready. chỉ ngắn ở bề ngoài; khi thiếu are, các từ không còn tạo thành một câu khẳng định tiếng Anh đầy đủ. Trong hội thoại, You’re nghe tự nhiên, còn dạng đầy đủ You are giúp ta kiểm tra phần được rút gọn. Vì thế dạng ngắn của You are ready. chính là You’re ready.',
      id: 'You’re ready. memiliki arti yang sama persis dengan You are ready.: “kamu siap”. Apostrof menandai tempat huruf a yang dihilangkan, jadi makna dan fungsi are tetap ada. You ready. hanya tampak lebih pendek; tanpa are, kata-kata itu tidak lagi membentuk pernyataan bahasa Inggris yang lengkap. Dalam percakapan, You’re terdengar alami, sedangkan bentuk lengkap You are memperlihatkan isi singkatannya. Jadi bentuk pendek You are ready. adalah You’re ready.',
      tr: 'You’re ready. ile You are ready. tam olarak aynı anlama gelir: “Hazırsın”. Kesme işareti atılan a harfinin yerini gösterir; bu yüzden are hem anlamda hem dil bilgisinde hâlâ vardır. You ready. yalnız görünüşte daha kısadır; are olmadan sözcükler tam bir İngilizce bildirim kurmaz. Konuşmada You’re doğal duyulur, açık You are biçimi ise kısaltmanın içinde ne bulunduğunu gösterir. Bu nedenle You are ready. cümlesinin kısa biçimi You’re ready. olur.',
      pl: 'You’re ready. znaczy dokładnie to samo co You are ready.: „jesteś gotowy”. Apostrof zaznacza miejsce pominiętej litery a, więc are nadal pozostaje w znaczeniu i gramatyce. You ready. jest krótsze tylko z wyglądu; bez are słowa nie tworzą pełnego angielskiego stwierdzenia. W rozmowie You’re brzmi naturalnie, a pełne You are pozwala sprawdzić, co kryje skrót. Dlatego krótką formą You are ready. jest You’re ready.',
    }),
    L({
      ru: 'You’re работает как готовое начало утверждения о собеседнике. После него можно назвать состояние — You’re calm., место — You’re here. или отрицание — You’re not busy. Внутри You’re уже находится are, поэтому форма You’re are ready. повторяет связку дважды и звучит неправильно. Not ставится после You’re, а затем идёт признак: You’re not busy. Сохраняйте сокращение единым блоком и меняйте только продолжение, когда смысл относится к тому же you.',
      uk: 'You’re працює як готовий початок твердження про співрозмовника. Після нього можна назвати стан — You’re calm., місце — You’re here. або заперечення — You’re not busy. Усередині You’re уже є are, тому форма You’re are ready. повторює зв’язку двічі й звучить неправильно. Not стоїть після You’re, а далі йде ознака: You’re not busy. Зберігайте скорочення одним блоком і змінюйте лише продовження, коли зміст стосується того самого you.',
      es: 'You’re funciona como un comienzo completo para afirmar algo sobre la otra persona. Después puede aparecer un estado — You’re calm., un lugar — You’re here. o una negación — You’re not busy. Como You’re ya contiene are, You’re are ready. repite el enlace dos veces y resulta incorrecto. Not se coloca después de You’re y antes de la cualidad: You’re not busy. Mantén la contracción como un bloque y cambia solo el final cuando sigues hablando del mismo you.',
      'pt-BR': 'You’re funciona como um começo completo para afirmar algo sobre a outra pessoa. Depois dele pode vir um estado — You’re calm., um lugar — You’re here. ou uma negação — You’re not busy. Como You’re já contém are, You’re are ready. repete a ligação duas vezes e fica errado. Not vem depois de You’re e antes da característica: You’re not busy. Mantenha a contração como um bloco e mude apenas o final quando continuar falando do mesmo you.',
      vi: 'You’re là phần mở đầu hoàn chỉnh của một lời khẳng định về người nghe. Sau đó có thể là trạng thái — You’re calm., nơi chốn — You’re here. hoặc phủ định — You’re not busy. Vì You’re đã chứa are, You’re are ready. lặp lại từ nối hai lần và trở thành câu sai. Not đứng sau You’re rồi mới đến đặc điểm: You’re not busy. Hãy giữ nguyên cụm rút gọn và chỉ thay phần cuối khi vẫn nói về cùng một you.',
      id: 'You’re berfungsi sebagai awal lengkap untuk menyatakan sesuatu tentang lawan bicara. Sesudahnya dapat muncul keadaan — You’re calm., tempat — You’re here. atau penyangkalan — You’re not busy. Karena You’re sudah mengandung are, You’re are ready. mengulang penghubung dua kali dan menjadi salah. Not diletakkan setelah You’re, lalu diikuti sifat: You’re not busy. Pertahankan singkatan sebagai satu blok dan ubah hanya bagian akhirnya saat subjeknya tetap you.',
      tr: 'You’re, karşınızdaki kişi hakkında bildirim kuran hazır bir başlangıçtır. Ardından durum — You’re calm., yer — You’re here. ya da olumsuzluk — You’re not busy. gelebilir. You’re içinde are zaten bulunduğu için You’re are ready. bağı iki kez söyler ve yanlış olur. Not, You’re sonrasında ve özellikten önce yer alır: You’re not busy. Aynı you kişisinden söz ederken kısaltmayı tek parça tutup yalnız son bölümü değiştirin.',
      pl: 'You’re działa jak gotowy początek stwierdzenia o rozmówcy. Dalej można podać stan — You’re calm., miejsce — You’re here. albo przeczenie — You’re not busy. Ponieważ You’re zawiera już are, forma You’re are ready. powtarza łącznik dwa razy i jest błędna. Not stoi po You’re, a przed cechą: You’re not busy. Traktuj skrót jako jeden blok i zmieniaj tylko zakończenie, gdy nadal mówisz o tej samej osobie you.',
    }),
    L({
      ru: 'You’re и your звучат одинаково, но выполняют разную работу. You’re раскрывается как you are, поэтому перед признаком получается You’re ready. или You’re tired. Your показывает принадлежность и требует после себя название вещи: your book, your bag. В предложении «Твоя книга здесь» нужна полная связь Your book is here., потому что book — вещь владельца, а is связывает её с here. Форма You’re book is here. ошибочно превращает начало в you are book, то есть «ты являешься книгой».',
      uk: 'You’re і your звучать однаково, але виконують різну роботу. You’re розкривається як you are, тому перед ознакою виходить You’re ready. або You’re tired. Your показує належність і потребує після себе назви речі: your book, your bag. У реченні «Твоя книга тут» потрібний повний зв’язок Your book is here., бо book — річ власника, а is пов’язує її з here. Форма You’re book is here. помилково перетворює початок на you are book, тобто «ти є книгою».',
      es: 'You’re y your suenan igual, pero cumplen funciones distintas. You’re se desarrolla como you are, por eso puede ir antes de una cualidad: You’re ready. o You’re tired. Your expresa posesión y necesita después el nombre de una cosa: your book, your bag. Para decir «tu libro está aquí» hace falta la estructura completa Your book is here., porque book es la cosa poseída e is la une con here. You’re book is here. empezaría como you are book y convertiría a la persona en un libro.',
      'pt-BR': 'You’re e your têm o mesmo som, mas fazem trabalhos diferentes. You’re se abre como you are e por isso vem antes de uma característica: You’re ready. ou You’re tired. Your indica posse e precisa do nome de uma coisa depois: your book, your bag. Para dizer «seu livro está aqui», a ligação completa é Your book is here., porque book é a coisa possuída e is a liga a here. You’re book is here. começaria como you are book e transformaria a pessoa num livro.',
      vi: 'You’re và your phát âm giống nhau nhưng giữ hai chức năng khác nhau. You’re mở rộng thành you are nên đứng trước đặc điểm, như You’re ready. hoặc You’re tired. Your chỉ sự sở hữu và phải đi với tên một vật ở phía sau: your book, your bag. Muốn nói “quyển sách của bạn ở đây”, cần câu đầy đủ Your book is here., vì book là vật được sở hữu còn is nối nó với here. You’re book is here. lại bắt đầu bằng nghĩa you are book, như thể người nghe là một quyển sách.',
      id: 'You’re dan your terdengar sama, tetapi tugasnya berbeda. You’re dapat dibuka menjadi you are, sehingga dipakai sebelum sifat seperti You’re ready. atau You’re tired. Your menunjukkan kepemilikan dan harus diikuti nama benda: your book, your bag. Untuk mengatakan “bukumu ada di sini”, bentuk lengkapnya Your book is here., karena book adalah benda milikmu dan is menghubungkannya dengan here. You’re book is here. justru bermula sebagai you are book, seolah-olah orangnya adalah buku.',
      tr: 'You’re ile your aynı duyulur, fakat görevleri farklıdır. You’re açıldığında you are olur; bu yüzden You’re ready. ya da You’re tired. gibi bir özelliğin önüne gelir. Your sahiplik gösterir ve ardından bir nesne adı ister: your book, your bag. “Kitabın burada” demek için tam bağ Your book is here. olmalıdır; book sahip olunan şeydir, is onu here ile bağlar. You’re book is here. ise you are book diye başlayarak kişiyi kitapmış gibi gösterir.',
      pl: 'You’re i your brzmią tak samo, lecz wykonują inną pracę. You’re rozwija się do you are, dlatego stoi przed cechą: You’re ready. albo You’re tired. Your oznacza przynależność i wymaga po sobie nazwy rzeczy: your book, your bag. Zdanie „twoja książka jest tutaj” ma pełną postać Your book is here., bo book jest posiadaną rzeczą, a is łączy ją z here. You’re book is here. zaczynałoby się jak you are book, czyli robiłoby z rozmówcy książkę.',
    }),
  ],
  14: [
    L({
      ru: 'Чтобы назвать место, английская фраза сохраняет связку перед ним: I am at home. — «Я дома», You are in class. — «Ты на занятии». По-русски можно сказать два коротких слова без отдельного «есть», но форма I at home. остаётся неполной. С I нужна am, а с you — are. После связки идёт не один предлог, а готовое название места. Поэтому полная фраза «Я дома» звучит I am at home.',
      uk: 'Щоб назвати місце, англійська фраза зберігає зв’язку перед ним: I am at home. — «Я вдома», You are in class. — «Ти на занятті». Українською можна обійтися без окремого «є», але форма I at home. лишається неповною. З I потрібне am, а з you — are. Після зв’язки йде не один прийменник, а готова назва місця. Тому повна фраза «Я вдома» звучить I am at home.',
      es: 'Para indicar un lugar, la frase inglesa conserva el enlace delante: I am at home. significa «estoy en casa» y You are in class. significa «estás en clase». En español estoy o estás reúne persona y verbo, pero I at home. queda incompleto en inglés. I necesita am y you necesita are. Después aparece el lugar como un bloque, no una preposición suelta. Por eso «estoy en casa» se expresa I am at home.',
      'pt-BR': 'Para indicar um lugar, a frase inglesa mantém a ligação antes dele: I am at home. significa «estou em casa» e You are in class. significa «você está na aula». Em português, estou já reúne pessoa e verbo, mas I at home. fica incompleto em inglês. I precisa de am e you precisa de are. Depois vem o lugar como bloco, não uma preposição solta. Assim, «estou em casa» é I am at home.',
      vi: 'Khi nói vị trí, câu tiếng Anh vẫn cần từ nối đứng trước nơi chốn: I am at home. nghĩa là “tôi ở nhà”, còn You are in class. nghĩa là “bạn đang ở lớp”. Tiếng Việt có thể dùng ở mà không đổi theo người, nhưng I at home. vẫn thiếu trong tiếng Anh. I đi với am, you đi với are. Phía sau là cả cụm nơi chốn chứ không phải một giới từ riêng. Vì vậy “tôi ở nhà” là I am at home.',
      id: 'Untuk menyatakan tempat, kalimat Inggris tetap memakai penghubung sebelum lokasi: I am at home. berarti “saya di rumah” dan You are in class. berarti “kamu sedang mengikuti kelas”. Bahasa Indonesia cukup memakai di, tetapi I at home. tidak lengkap dalam bahasa Inggris. I memerlukan am dan you memerlukan are. Sesudahnya datang satu kelompok tempat, bukan preposisi lepas. Jadi “saya di rumah” ialah I am at home.',
      tr: 'Yer bildirirken İngilizce cümlede yerden önce bağ açıkça kalır: I am at home. “Evdeyim”, You are in class. “Derstesin” demektir. Türkçede kişi ve yer eklerle birleşebilir, fakat I at home. İngilizcede eksiktir. I ile am, you ile are gerekir. Ardından tek başına bir edat değil, hazır yer grubu gelir. Bu nedenle “Evdeyim” cümlesi I am at home. olur.',
      pl: 'Gdy podajesz miejsce, angielskie zdanie zachowuje łącznik przed nim: I am at home. znaczy „jestem w domu”, a You are in class. — „jesteś na zajęciach”. Po polsku osobna forma „być” jest widoczna, lecz łatwo skupić się tylko na miejscu; I at home. pozostaje niepełne. I wymaga am, a you — are. Potem pojawia się cały blok miejsca. Dlatego „jestem w domu” to I am at home.',
    }),
    L({
      ru: 'Место лучше запоминать вместе с его маленьким началом: at home, in class, at work, in the park, at the station, on the bus. Эти сочетания не строятся каждый раз заново. Сначала выбирается нужный блок, затем он ставится после I am или You are: I am at work., You are in the park. Для поездки пассажиром используется on the bus, поэтому «Ты едешь в автобусе» — You are on the bus. Сохраняйте весь конец фразы целиком.',
      uk: 'Місце краще запам’ятовувати разом із його коротким початком: at home, in class, at work, in the park, at the station, on the bus. Ці сполуки не будуються щоразу наново. Спочатку обирається потрібний блок, потім він стає після I am або You are: I am at work., You are in the park. Для поїздки пасажиром уживається on the bus, тому «Ти їдеш автобусом» — You are on the bus. Зберігайте весь кінець фрази разом.',
      es: 'Conviene aprender cada lugar con su comienzo pequeño: at home, in class, at work, in the park, at the station, on the bus. Esos grupos no se reconstruyen palabra por palabra cada vez. Primero recuperas el bloque y luego lo colocas después de I am o You are: I am at work., You are in the park. Para viajar como pasajero se usa on the bus; por eso «vas en el autobús» es You are on the bus. Mantén unido todo el final.',
      'pt-BR': 'É melhor aprender cada lugar junto com seu pequeno começo: at home, in class, at work, in the park, at the station, on the bus. Esses grupos não são reconstruídos palavra por palavra toda vez. Primeiro se recupera o bloco e depois ele vem após I am ou You are: I am at work., You are in the park. Para viajar como passageiro usa-se on the bus; assim «você está no ônibus» é You are on the bus. Mantenha o final inteiro unido.',
      vi: 'Nên ghi nhớ mỗi nơi cùng với phần mở đầu ngắn của nó: at home, in class, at work, in the park, at the station, on the bus. Không cần lắp lại từng cụm từ đầu mỗi lần nói. Hãy nhớ cả khối rồi đặt sau I am hoặc You are: I am at work., You are in the park. Khi đi xe buýt như hành khách, tiếng Anh dùng on the bus; vì vậy “bạn đang đi xe buýt” là You are on the bus. Giữ nguyên cả phần cuối.',
      id: 'Setiap tempat sebaiknya diingat bersama awal kecilnya: at home, in class, at work, in the park, at the station, on the bus. Kelompok itu tidak perlu dirakit ulang kata demi kata. Ambil kelompok yang tepat lalu letakkan setelah I am atau You are: I am at work., You are in the park. Untuk bepergian sebagai penumpang dipakai on the bus; jadi “kamu sedang naik bus” adalah You are on the bus. Pertahankan seluruh bagian akhir.',
      tr: 'Her yeri küçük başlangıcıyla birlikte öğrenmek daha güvenlidir: at home, in class, at work, in the park, at the station, on the bus. Bu gruplar her seferinde sözcük sözcük yeniden kurulmaz. Uygun bütünü hatırlayıp I am ya da You are sonrasına getirin: I am at work., You are in the park. Otobüste yolcu olarak giderken on the bus kullanılır; bu yüzden “Otobüstesin” You are on the bus. olur. Son bölümü bütün tutun.',
      pl: 'Każde miejsce najlepiej zapamiętać wraz z jego krótkim początkiem: at home, in class, at work, in the park, at the station, on the bus. Tych połączeń nie układa się za każdym razem od nowa. Przywołaj cały blok i postaw go po I am albo You are: I am at work., You are in the park. Podróż pasażera autobusu wyraża on the bus, więc „jedziesz autobusem” to You are on the bus. Zachowaj całe zakończenie.',
    }),
    L({
      ru: 'At, in и on нельзя бездумно менять местами. At home означает «дома», in the park подчёркивает нахождение внутри парка, а on the bus — поездку пассажиром. Другой предлог иногда возможен в другой ситуации, но меняет точный взгляд на место. Если нужно сказать именно «Я внутри парка», выбирается in the park: I am in the park. Форма I am at the park. сообщает лишь о нахождении у парка или в этой точке и не передаёт тот же точный смысл. Сначала определите ситуацию, затем восстановите готовый блок.',
      uk: 'At, in та on не можна бездумно міняти місцями. At home означає «удома», in the park підкреслює перебування всередині парку, а on the bus — поїздку пасажиром. Інший прийменник іноді можливий в іншій ситуації, але змінює точний погляд на місце. Якщо треба сказати саме «Я всередині парку», обирається in the park: I am in the park. Форма I am at the park. лише позначає парк як точку й не передає того самого змісту. Спершу визначте ситуацію, потім відновіть готовий блок.',
      es: 'At, in y on no se intercambian sin pensar. At home significa estar en casa, in the park destaca que alguien está dentro del parque y on the bus presenta un viaje como pasajero. Otra preposición puede existir en otra situación, pero cambia el punto de vista exacto. Si quieres decir «estoy dentro del parque», necesitas in the park: I am in the park. I am at the park. solo sitúa el parque como punto y no expresa el mismo interior. Decide primero la situación y recupera después el bloque completo.',
      'pt-BR': 'At, in e on não podem trocar de lugar sem atenção. At home significa estar em casa, in the park destaca que alguém está dentro do parque e on the bus apresenta uma viagem como passageiro. Outra preposição pode funcionar em outra situação, mas muda o ponto de vista exato. Para dizer «estou dentro do parque», é preciso in the park: I am in the park. I am at the park. apenas trata o parque como ponto e não expressa o mesmo interior. Defina a situação e então recupere o bloco inteiro.',
      vi: 'Không thể đổi at, in và on cho nhau theo thói quen. At home nghĩa là ở nhà, in the park nhấn mạnh ở bên trong công viên, còn on the bus nói về việc đi xe như hành khách. Một giới từ khác có thể xuất hiện trong tình huống khác nhưng sẽ đổi góc nhìn chính xác. Muốn nói “tôi ở bên trong công viên”, cần in the park: I am in the park. I am at the park. chỉ coi công viên là một điểm đến, không giữ cùng ý nghĩa. Hãy xác định tình huống rồi nhớ lại cả cụm.',
      id: 'At, in, dan on tidak dapat ditukar tanpa memperhatikan situasi. At home berarti berada di rumah, in the park menekankan posisi di dalam taman, sedangkan on the bus menggambarkan perjalanan sebagai penumpang. Preposisi lain mungkin cocok pada konteks lain, tetapi sudut pandangnya berubah. Untuk mengatakan “saya berada di dalam taman”, gunakan in the park: I am in the park. I am at the park. hanya menjadikan taman sebagai titik lokasi. Tentukan situasinya lalu ingat kelompok lengkapnya.',
      tr: 'At, in ve on düşünmeden birbirinin yerine konmaz. At home evde olmayı, in the park parkın içinde bulunmayı, on the bus ise yolcu olarak seyahat etmeyi anlatır. Başka bir edat başka durumda mümkün olabilir, fakat yere bakış değişir. “Parkın içindeyim” demek için in the park gerekir: I am in the park. I am at the park. yalnız parkı bir konum noktası yapar ve aynı iç anlamını vermez. Önce durumu seçin, sonra bütün grubu hatırlayın.',
      pl: 'At, in i on nie są wymienne bez zmiany znaczenia. At home oznacza bycie w domu, in the park podkreśla wnętrze parku, a on the bus opisuje podróż pasażera. Inny przyimek może być możliwy w innej sytuacji, lecz zmieni dokładny punkt widzenia. Gdy chodzi o „jestem wewnątrz parku”, potrzebne jest in the park: I am in the park. I am at the park. traktuje park tylko jako punkt i nie przekazuje tego samego wnętrza. Najpierw wybierz sytuację, potem cały blok.',
    }),
  ],
  15: [
    L({
      ru: 'Are you ready? и Am I ready? спрашивают об одном состоянии, но направляют вопрос разным людям. Начало Are you обращается к собеседнику: ответ должен прийти от человека напротив. Начало Am I спрашивает о самом говорящем: он просит другого подтвердить его состояние. Слово ready в конце не выбирает человека — это делают первые два слова. Поэтому при речи сначала решите, о ком вопрос, произнесите цельное Are you или Am I и только затем добавляйте ready, okay или знакомое место.',
      uk: 'Are you ready? та Am I ready? питають про однаковий стан, але спрямовують запитання різним людям. Початок Are you звертається до співрозмовника: відповідь має дати людина навпроти. Початок Am I питає про самого мовця: він просить іншого підтвердити його стан. Слово ready наприкінці не визначає людину — це роблять перші два слова. Тому спочатку вирішіть, про кого запитання, вимовте цілісне Are you або Am I, а вже потім додайте ready, okay чи знайоме місце.',
      es: 'Are you ready? y Am I ready? preguntan por el mismo estado, pero dirigen la pregunta a personas distintas. Are you se dirige al interlocutor y espera una respuesta sobre esa persona. Am I pregunta por quien habla y pide al otro que confirme su estado. La palabra ready del final no decide la persona; esa información aparece en las dos primeras palabras. Al hablar, elige primero a quién se refiere la pregunta, pronuncia Are you o Am I como un comienzo unido y añade después ready, okay o un lugar conocido.',
      'pt-BR': 'Are you ready? e Am I ready? perguntam sobre o mesmo estado, mas apontam para pessoas diferentes. Are you se dirige ao interlocutor e espera uma resposta sobre ele. Am I pergunta sobre quem fala e pede ao outro que confirme essa condição. A palavra ready no final não escolhe a pessoa; essa informação já está nas duas primeiras palavras. Ao falar, decida primeiro de quem é a pergunta, diga Are you ou Am I como um começo unido e só então acrescente ready, okay ou um lugar conhecido.',
      vi: 'Are you ready? và Am I ready? cùng hỏi về một trạng thái nhưng hướng tới hai người khác nhau. Are you hỏi người nghe và chờ câu trả lời về người đối diện. Am I hỏi về chính người nói và nhờ người nghe xác nhận tình trạng ấy. Từ ready ở cuối không quyết định người nào; hai từ mở đầu đã làm việc đó. Khi nói, hãy chọn người trước, phát âm liền Are you hoặc Am I, rồi mới thêm ready, okay hay một địa điểm quen thuộc.',
      id: 'Are you ready? dan Am I ready? menanyakan keadaan yang sama, tetapi pertanyaannya diarahkan kepada orang yang berbeda. Are you ditujukan kepada lawan bicara dan meminta jawaban tentang orang itu. Am I menanyakan penutur sendiri dan meminta orang lain memastikan keadaannya. Kata ready di akhir tidak menentukan orang; dua kata pembuka sudah melakukannya. Saat berbicara, tentukan dahulu siapa yang ditanyakan, ucapkan Are you atau Am I sebagai satu awal, lalu tambahkan ready, okay, atau tempat yang sudah dikenal.',
      tr: 'Are you ready? ile Am I ready? aynı durumu sorar, fakat soru farklı kişilere yönelir. Are you karşınızdaki kişiye seslenir ve onunla ilgili cevap bekler. Am I konuşanın kendisini sorar ve diğer kişiden durumunu doğrulamasını ister. Sondaki ready kimin sorulduğunu seçmez; bu bilgiyi ilk iki sözcük verir. Konuşurken önce kişiyi belirleyin, Are you ya da Am I başlangıcını bir bütün olarak söyleyin, ardından ready, okay veya tanıdık bir yer ekleyin.',
      pl: 'Are you ready? i Am I ready? pytają o ten sam stan, lecz kierują pytanie do różnych osób. Are you zwraca się do rozmówcy i oczekuje odpowiedzi o nim. Am I pyta o samego mówiącego i prosi drugą osobę o potwierdzenie jego stanu. Końcowe ready nie wybiera osoby; robią to pierwsze dwa słowa. Podczas mówienia najpierw ustal, kogo dotyczy pytanie, wypowiedz Are you albo Am I jako jeden początek, a dopiero potem dodaj ready, okay lub znane miejsce.',
    }),
    L({
      ru: 'Вопрос и ответ используют те же слова, но меняют порядок. Am I ready? начинается со связки, потому что говорящий задаёт вопрос о себе; спокойный ответ возвращает I на первое место: I am ready. С собеседником работает та же пара: Are you okay? превращается в You’re okay., где You’re уже содержит you are. Не переносите начало вопроса в ответ и не отвечайте формой Am I. Услышав вопрос, сначала выберите человека, затем верните прямой порядок I am или You’re и закончите тем же состоянием либо местом. Поэтому полный ответ «Ты готов» звучит You’re ready.',
      uk: 'Запитання й відповідь використовують ті самі слова, але змінюють порядок. Am I ready? починається зі зв’язки, бо мовець запитує про себе; спокійна відповідь повертає I на перше місце: I am ready. Зі співрозмовником працює та сама пара: Are you okay? перетворюється на You’re okay., де You’re уже містить you are. Не переносьте початок запитання у відповідь і не відповідайте формою Am I. Почувши запитання, спочатку оберіть людину, потім поверніть прямий порядок I am або You’re і завершіть тим самим станом чи місцем. Тому повна відповідь «Ти готовий» звучить You’re ready.',
      es: 'La pregunta y la respuesta usan las mismas piezas, pero cambian el orden. Am I ready? comienza con el enlace porque quien habla pregunta por sí mismo; la respuesta tranquila devuelve I al primer lugar: I am ready. Con el interlocutor funciona la misma relación: Are you okay? pasa a You’re okay., donde You’re ya contiene you are. No conserves el comienzo interrogativo dentro de la respuesta ni respondas con Am I. Al oír la pregunta, identifica primero a la persona, recupera el orden directo I am o You’re y termina con el mismo estado o lugar. Por eso «estás listo» se responde You’re ready.',
      'pt-BR': 'A pergunta e a resposta usam as mesmas peças, mas mudam a ordem. Am I ready? começa com a ligação porque quem fala pergunta sobre si; a resposta tranquila devolve I ao primeiro lugar: I am ready. Com o interlocutor ocorre a mesma relação: Are you okay? vira You’re okay., em que You’re já contém you are. Não mantenha o começo interrogativo dentro da resposta nem responda com Am I. Ao ouvir a pergunta, identifique a pessoa, recupere a ordem direta I am ou You’re e termine com o mesmo estado ou lugar. Por isso «você está pronto» é You’re ready.',
      vi: 'Câu hỏi và câu trả lời dùng cùng những mảnh quen thuộc nhưng đổi trật tự. Am I ready? đưa từ nối lên đầu vì người nói đang hỏi về mình; câu trả lời bình thường đưa I trở lại trước: I am ready. Với người nghe cũng vậy: Are you okay? đổi thành You’re okay., trong đó You’re đã chứa you are. Đừng giữ phần mở đầu của câu hỏi trong câu trả lời và đừng đáp bằng Am I. Sau khi nghe, hãy xác định người, trở về trật tự I am hoặc You’re, rồi giữ nguyên trạng thái hay địa điểm ở cuối. Vì vậy câu “bạn đã sẵn sàng” là You’re ready.',
      id: 'Pertanyaan dan jawaban memakai bagian yang sama, tetapi urutannya berubah. Am I ready? menaruh penghubung di depan karena penutur bertanya tentang dirinya; jawaban biasa mengembalikan I ke awal: I am ready. Untuk lawan bicara berlaku pasangan yang sama: Are you okay? menjadi You’re okay., dan You’re sudah mengandung you are. Jangan membawa awal pertanyaan ke dalam jawaban dan jangan menjawab dengan Am I. Setelah mendengar pertanyaan, tentukan orangnya, kembalikan urutan I am atau You’re, lalu pertahankan keadaan atau tempat yang sama. Karena itu “kamu siap” berbentuk You’re ready.',
      tr: 'Soru ve cevap aynı parçaları kullanır, fakat sıraları değişir. Am I ready? konuşan kendisini sorduğu için bağla başlar; sakin cevap I sözcüğünü yeniden öne alır: I am ready. Karşıdaki kişi için de aynı ilişki vardır: Are you okay? sorusu You’re okay. cevabına döner ve You’re içinde you are zaten bulunur. Soru başlangıcını cevabın içinde tutmayın ve Am I diye cevap vermeyin. Soruyu duyunca önce kişiyi seçin, I am ya da You’re düz sırasına dönün, aynı durum veya yerle bitirin. Bu yüzden “Hazırsın” cevabı You’re ready. olur.',
      pl: 'Pytanie i odpowiedź korzystają z tych samych części, lecz zmieniają ich szyk. Am I ready? zaczyna się od łącznika, bo mówiący pyta o siebie; spokojna odpowiedź przywraca I na pierwsze miejsce: I am ready. Dla rozmówcy działa ta sama para: Are you okay? przechodzi w You’re okay., gdzie You’re zawiera już you are. Nie przenoś początku pytania do odpowiedzi i nie odpowiadaj formą Am I. Po usłyszeniu pytania wybierz osobę, wróć do prostego I am albo You’re i zachowaj ten sam stan lub miejsce. Dlatego pełne „jesteś gotowy” brzmi You’re ready.',
    }),
    L({
      ru: 'Одной вопросительной интонации недостаточно, если порядок остаётся утвердительным. Форма I am at home. сообщает место, а нейтральный вопрос начинается Am I at home?; вариант I am at home? звучит как удивлённый переспрос, а не обычная просьба подтвердить место. Нельзя также выбрасывать маленькие слова и оставлять I at home? или you okay?: смысл угадывается, но английская связь исчезает. Для точной реплики восстановите всё начало целиком. В вопросе связка стоит перед человеком, а в ответе человек снова выходит первым. Полное утверждение о собеседнике в классе звучит You’re in class.',
      uk: 'Самої питальної інтонації недостатньо, якщо порядок залишається стверджувальним. Форма I am at home. повідомляє місце, а нейтральне запитання починається Am I at home?; варіант I am at home? звучить як здивоване перепитування, а не звичайне прохання підтвердити місце. Не можна також викидати короткі слова й залишати I at home? або you okay?: зміст можна вгадати, але англійський зв’язок зникає. Для точної репліки відновіть увесь початок. У запитанні зв’язка стоїть перед людиною, а у відповіді людина знову виходить першою. Повне твердження про співрозмовника в класі звучить You’re in class.',
      es: 'La entonación interrogativa no basta si el orden sigue siendo afirmativo. I am at home. informa de un lugar, mientras que la pregunta neutral comienza Am I at home?; I am at home? suena a eco sorprendido, no a una petición normal de confirmación. Tampoco se pueden eliminar las palabras pequeñas y dejar I at home? o you okay?: el sentido quizá se adivine, pero desaparece el enlace inglés. Para producir una frase precisa, recupera todo el comienzo. En la pregunta, el enlace va antes de la persona; en la respuesta, la persona vuelve al primer lugar. La afirmación completa sobre el interlocutor es You’re in class.',
      'pt-BR': 'A entonação de pergunta não basta quando a ordem continua afirmativa. I am at home. informa um lugar, enquanto a pergunta neutra começa Am I at home?; I am at home? soa como eco surpreso, não como um pedido normal de confirmação. Também não se pode apagar as palavras pequenas e deixar I at home? ou you okay?: talvez o sentido seja adivinhado, mas a ligação inglesa desaparece. Para dizer a frase com precisão, recupere o começo inteiro. Na pergunta, a ligação vem antes da pessoa; na resposta, a pessoa volta ao primeiro lugar. A afirmação completa sobre o interlocutor é You’re in class.',
      vi: 'Chỉ nâng giọng ở cuối chưa đủ nếu trật tự vẫn là câu kể. I am at home. thông báo địa điểm, còn câu hỏi trung tính phải bắt đầu Am I at home?; I am at home? nghe giống câu hỏi nhắc lại vì ngạc nhiên hơn là lời xác nhận bình thường. Cũng không được bỏ các từ nhỏ để chỉ còn I at home? hoặc you okay?: người nghe có thể đoán ý nhưng mối nối tiếng Anh đã mất. Muốn nói chính xác, hãy khôi phục toàn bộ phần đầu. Trong câu hỏi, từ nối đứng trước người; trong câu trả lời, người lại đứng đầu. Câu đầy đủ nói người nghe đang ở lớp là You’re in class.',
      id: 'Intonasi bertanya saja tidak cukup jika urutannya masih berupa pernyataan. I am at home. memberitahukan tempat, sedangkan pertanyaan netral harus dimulai Am I at home?; I am at home? terdengar seperti pertanyaan gema karena terkejut, bukan permintaan konfirmasi biasa. Kata-kata kecil juga tidak boleh dibuang hingga tersisa I at home? atau you okay?: maknanya mungkin dapat ditebak, tetapi hubungan Inggrisnya hilang. Untuk ucapan yang tepat, pulihkan seluruh awal. Dalam pertanyaan penghubung mendahului orang; dalam jawaban orang kembali ke depan. Pernyataan lengkap tentang lawan bicara di kelas adalah You’re in class.',
      tr: 'Sıra bildirim olarak kalıyorsa yalnız soru tonlaması yetmez. I am at home. yeri bildirir; nötr soru ise Am I at home? diye başlar. I am at home? şaşkın bir yankı sorusu gibi duyulur, sıradan bir doğrulama isteği değildir. Küçük sözcükleri atıp I at home? ya da you okay? bırakmak da olmaz: anlam tahmin edilebilir, fakat İngilizce bağ kaybolur. Kesin bir söz için başlangıcın tamamını geri getirin. Soruda bağ kişiden önce, cevapta kişi yeniden ilk sıradadır. Karşıdaki kişinin derste olduğunu söyleyen tam bildirim You’re in class. olur.',
      pl: 'Sama intonacja pytająca nie wystarcza, gdy szyk pozostaje oznajmujący. I am at home. podaje miejsce, natomiast neutralne pytanie zaczyna się Am I at home?; I am at home? brzmi raczej jak zaskoczone pytanie echo niż zwykła prośba o potwierdzenie. Nie wolno też usuwać małych słów i zostawiać I at home? albo you okay?: sens można odgadnąć, lecz znika angielski łącznik. Aby wypowiedź była dokładna, odtwórz cały początek. W pytaniu łącznik stoi przed osobą, a w odpowiedzi osoba znów wraca na pierwsze miejsce. Pełne stwierdzenie o rozmówcy na zajęciach brzmi You’re in class.',
    }),
  ],
});
